package main

import (
	"bytes"
	"io"
	"net/http"
	"os"
	"path"

	"github.com/cubefs/cubefs/blobstore/cmd"
	"github.com/cubefs/cubefs/blobstore/common/config"
	"github.com/cubefs/cubefs/blobstore/common/rpc"
	"github.com/cubefs/cubefs/blobstore/common/rpc2"
	"github.com/cubefs/cubefs/blobstore/util/log"
)

type Config struct {
	cmd.Config
}

func init() {
	mod := &cmd.Module{
		Name:       "example_rpc2",
		InitConfig: initConfig,
		SetUp:      setUp,
		SetUp2:     setUp2,
		TearDown:   func() {},
	}
	cmd.RegisterModule(mod)
}

func initConfig(args []string) (*cmd.Config, error) {
	var conf Config
	config.Init("f", "", "server.conf")
	if err := config.Load(&conf); err != nil {
		return nil, err
	}
	logDir := path.Join(os.TempDir(), "example_rpc2")
	os.MkdirAll(logDir, 0o644)
	conf.AuditLog.LogDir = logDir
	if conf.Log == nil {
		conf.Log = &log.AsyncLogger{}
	}
	conf.Log.Filename = path.Join(logDir, "rpc2.log")
	conf.BindAddr = listenrpc
	conf.Rpc2Server.Addresses = []rpc2.NetworkAddress{
		{Network: "tcp", Address: listenon[0]},
		{Network: "tcp", Address: listenon[1]},
	}
	return &conf.Config, nil
}

func setUp() (*rpc.Router, []rpc.ProgressHandler) {
	router := rpc.New()
	router.Handle(http.MethodGet, "/rpc", func(c *rpc.Context) { c.Respond() })
	return router, nil
}

func setUp2() (*rpc2.Router, []rpc2.Interceptor) {
	router := &rpc2.Router{}
	router.Middleware(handleMiddleware1, handleMiddleware2)
	router.Register("/ping", handlePing)
	router.Register("/kick", handleKick)
	router.Register("/error", handleError)
	router.Register("/panic", handlePanic)
	router.Register("/stream", handleStream)
	return router, []rpc2.Interceptor{interceptor{"i1"}, interceptor{"i2"}}
}

type interceptor struct{ id string }

func (i interceptor) Handle(w rpc2.ResponseWriter, req *rpc2.Request, h rpc2.Handle) error {
	log.Info("interceptor-" + i.id)
	return h(w, req)
}

func handleMiddleware1(w rpc2.ResponseWriter, req *rpc2.Request) error {
	log.Info("middleware-1")
	return nil
}

func handleMiddleware2(w rpc2.ResponseWriter, req *rpc2.Request) error {
	log.Info("middleware-2")
	return nil
}

func handleKick(_ rpc2.ResponseWriter, req *rpc2.Request) error {
	var para paraCodec
	req.ParseParameter(&para)
	return nil
}

func handleError(rpc2.ResponseWriter, *rpc2.Request) error {
	return rpc2.NewError(567, "", "")
}

func handlePanic(rpc2.ResponseWriter, *rpc2.Request) error {
	panic("handle panic")
}

func handlePing(w rpc2.ResponseWriter, req *rpc2.Request) error {
	log.Info(req.RequestHeader.String())
	var para paraCodec
	req.ParseParameter(&para)

	resp := bytes.NewBuffer(nil)
	resp.WriteString("response -> ")
	w.SetContentLength(int64(resp.Len()) + req.ContentLength)
	buff := make([]byte, req.ContentLength)
	if _, err := io.ReadFull(req.Body, buff); err != nil {
		return err
	}
	req.Body.Close()
	log.Info("body   :", string(buff))
	log.Info("trailer:", req.Trailer.M)
	w.Trailer().SetLen("server-trailer", 3)
	w.AfterBody(func() error {
		log.Info("run after body stack - 1")
		w.Trailer().Set("server-trailer", "123")
		return nil
	})
	w.AfterBody(func() error {
		log.Info("run after body stack - 2")
		return nil
	})

	w.WriteHeader(200, &para)
	w.Header().Set("ignored", "x") // ignore
	resp.Write(buff)
	_, err := w.ReadFrom(resp)
	return err
}

func handleStream(_ rpc2.ResponseWriter, req *rpc2.Request) error {
	var para paraCodec
	req.ParseParameter(&para)
	para.Value.S = "response -> " + para.Value.S

	stream := rpc2.GenericServerStream[streamReq, streamResp]{ServerStream: req.ServerStream()}
	var header, trailer rpc2.Header
	header.Set("stream-header-a", "aaa")
	trailer.Set("stream-trailer-b", "")
	stream.SetHeader(header)
	stream.SetTrailer(trailer)
	stream.SendHeader(&para)
	for {
		req, err := stream.Recv()
		if err == io.EOF {
			trailer.Set("stream-trailer-b", "bbb")
			trailer.Set("stream-trailer-x", "another")
			stream.SetTrailer(trailer)
			return nil
		}
		if err != nil {
			return err
		}
		var resp streamResp
		resp.Value = "response -> " + req.Value
		if err = stream.Send(&resp); err != nil {
			return err
		}
	}
}

func runServer() {
	cmd.Main(os.Args)
}

package main

import (
	"context"
	"fmt"
	"io"
	"time"

	"github.com/cubefs/cubefs/blobstore/common/rpc2"
	"github.com/cubefs/cubefs/blobstore/util/log"
)

type (
	streamReq  struct{ rpc2.AnyCodec[string] }
	streamResp struct{ rpc2.AnyCodec[string] }
)

func runStream() {
	client := rpc2.Client{ConnectorConfig: rpc2.ConnectorConfig{Network: "tcp"}}
	streamCli := rpc2.StreamClient[streamReq, streamResp]{Client: &client}

	var para paraCodec
	para.Value = message{I: 11, S: "stream string"}
	req, err := rpc2.NewStreamRequest(context.Background(),
		listenon[int(time.Now().UnixNano())%len(listenon)], "/stream", &para)
	if err != nil {
		panic(err)
	}

	var ret paraCodec
	cli, err := streamCli.Streaming(req, &ret)
	if err != nil {
		panic(err)
	}
	log.Infof("recv: result  %+v", ret)
	header, _ := cli.Header()
	log.Infof("recv: header  %+v", header.M)
	log.Infof("recv: trailer %+v", cli.Trailer().M)

	waitc := make(chan struct{})
	go func() {
		for {
			resp, errx := cli.Recv()
			if errx == io.EOF {
				close(waitc)
				return
			}
			if errx != nil {
				panic(errx)
			}
			log.Info("recv:", resp.Value)
		}
	}()
	for idx := range [10]struct{}{} {
		var req streamReq
		req.Value = fmt.Sprintf("request-%d", idx)
		log.Info("send:", req.Value)
		if err = cli.Send(&req); err != nil {
			panic(err)
		}
	}
	cli.CloseSend()
	<-waitc
	log.Infof("recv: trailer %+v", cli.Trailer().M)
	log.Info("done.")
}

// Clockfs implements a file system with the current time in a file.
// It was written to demonstrate kernel cache invalidation.
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/cubefs/cubefs/depends/bazil.org/fuse"
	"github.com/cubefs/cubefs/depends/bazil.org/fuse/fs"
	_ "github.com/cubefs/cubefs/depends/bazil.org/fuse/fs/fstestutil"
	"github.com/cubefs/cubefs/depends/bazil.org/fuse/fuseutil"
	"golang.org/x/net/context"
)

func usage() {
	fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
	fmt.Fprintf(os.Stderr, "  %s MOUNTPOINT\n", os.Args[0])
	flag.PrintDefaults()
}

func run(mountpoint string) error {
	c, err := fuse.Mount(
		mountpoint,
		fuse.FSName("clock"),
		fuse.Subtype("clockfsfs"),
		fuse.LocalVolume(),
		fuse.VolumeName("Clock filesystem"),
	)
	if err != nil {
		return err
	}
	defer c.Close()

	if p := c.Protocol(); !p.HasInvalidate() {
		return fmt.Errorf("kernel FUSE support is too old to have invalidations: version %v", p)
	}

	srv := fs.New(c, nil)
	filesys := &FS{
		// We pre-create the clock node so that it's always the same
		// object returned from all the Lookups. You could carefully
		// track its lifetime between Lookup&Forget, and have the
		// ticking & invalidation happen only when active, but let's
		// keep this example simple.
		clockFile: &File{
			fuse: srv,
		},
	}
	filesys.clockFile.tick()
	// This goroutine never exits. That's fine for this example.
	go filesys.clockFile.update()
	if err := srv.Serve(filesys, nil); err != nil {
		return err
	}

	// Check if the mount process has an error to report.
	<-c.Ready
	if err := c.MountError; err != nil {
		return err
	}
	return nil
}

func main() {
	flag.Usage = usage
	flag.Parse()

	if flag.NArg() != 1 {
		usage()
		os.Exit(2)
	}
	mountpoint := flag.Arg(0)

	if err := run(mountpoint); err != nil {
		log.Fatal(err)
	}
}

type FS struct {
	clockFile *File
}

var _ fs.FS = (*FS)(nil)

func (f *FS) Root() (fs.Node, error) {
	return &Dir{fs: f}, nil
}

// Dir implements both Node and Handle for the root directory.
type Dir struct {
	fs *FS
}

var _ fs.Node = (*Dir)(nil)

func (d *Dir) Attr(ctx context.Context, a *fuse.Attr) error {
	a.Inode = 1
	a.Mode = os.ModeDir | 0555
	return nil
}

var _ fs.NodeStringLookuper = (*Dir)(nil)

func (d *Dir) Lookup(ctx context.Context, name string) (fs.Node, error) {
	if name == "clock" {
		return d.fs.clockFile, nil
	}
	return nil, fuse.ENOENT
}

var dirDirs = []fuse.Dirent{
	{Inode: 2, Name: "clock", Type: fuse.DT_File},
}

var _ fs.HandleReadDirAller = (*Dir)(nil)

func (d *Dir) ReadDirAll(ctx context.Context) ([]fuse.Dirent, error) {
	return dirDirs, nil
}

type File struct {
	fs.NodeRef
	fuse    *fs.Server
	content atomic.Value
	count   uint64
}

var _ fs.Node = (*File)(nil)

func (f *File) Attr(ctx context.Context, a *fuse.Attr) error {
	a.Inode = 2
	a.Mode = 0444
	t := f.content.Load().(string)
	a.Size = uint64(len(t))
	return nil
}

var _ fs.NodeOpener = (*File)(nil)

func (f *File) Open(ctx context.Context, req *fuse.OpenRequest, resp *fuse.OpenResponse) (fs.Handle, error) {
	if !req.Flags.IsReadOnly() {
		return nil, fuse.Errno(syscall.EACCES)
	}
	resp.Flags |= fuse.OpenKeepCache
	return f, nil
}

var _ fs.Handle = (*File)(nil)

var _ fs.HandleReader = (*File)(nil)

func (f *File) Read(ctx context.Context, req *fuse.ReadRequest, resp *fuse.ReadResponse) error {
	t := f.content.Load().(string)
	fuseutil.HandleRead(req, resp, []byte(t))
	return nil
}

func (f *File) tick() {
	// Intentionally a variable-length format, to demonstrate size changes.
	f.count++
	s := fmt.Sprintf("%d\t%s\n", f.count, time.Now())
	f.content.Store(s)

	// For simplicity, this example tries to send invalidate
	// notifications even when the kernel does not hold a reference to
	// the node, so be extra sure to ignore ErrNotCached.
	if err := f.fuse.InvalidateNodeData(f); err != nil && err != fuse.ErrNotCached {
		log.Printf("invalidate error: %v", err)
	}
}

func (f *File) update() {
	tick := time.NewTicker(1 * time.Second)
	defer tick.Stop()
	for range tick.C {
		f.tick()
	}
}

