/* <DESC>
 * Download many files in parallel, in the same thread.
 * </DESC>
 */
#include <stdlib.h>
#include <string.h>

#include <curl/curl.h>

static const char * const urls[] = {
  "https://01.example/",
  "https://02.example/",
  "https://03.example/",
  "https://04.example/",
  "https://05.example/",
  "https://06.example/",
